# Small new valid-count parity fixture, generated by a requested real R run.
# Run from wt: Rscript hub/shared/tests/rev-p02-r3-reference.R
suppressPackageStartupMessages(library(dosresmeta))
num <- function(x) sprintf("%.17g", as.numeric(x))
vec <- function(x) paste0("[", paste(num(x), collapse=","), "]")
str <- function(x) paste0('"', gsub('["\\\\\n\r\t]', ' ', x), '"')
items <- character()
for (type in c("cc", "ci", "ir")) {
  d <- data.frame(id=rep(1:3, each=3), dose=rep(0:2, 3),
    cases=rep(c(10, 12, 14), 3) + rep(0:2, each=3), n=100, type=type)
  if (type == "ir") d$cases <- d$cases + 100
  d$logrr <- d$se <- 0
  for (id in 1:3) {
    ii <- which(d$id == id); a <- d$cases[ii]; n <- d$n[ii]
    effect <- if (type == "cc") log(a/(n-a)) else log(a/n)
    v <- switch(type, cc=1/a+1/(n-a), ci=1/a-1/n, ir=1/a)
    d$logrr[ii] <- effect-effect[1]
    d$se[ii] <- sqrt(v+v[1]); d$se[ii[1]] <- 0
  }
  rows <- vapply(seq_len(nrow(d)), function(i) paste0('{"id":"', d$id[i],
    '","dose":', num(d$dose[i]), ',"cases":', num(d$cases[i]), ',"n":', num(d$n[i]),
    ',"logrr":', num(d$logrr[i]), ',"se":', num(d$se[i]), ',"type":"', type, '"}'), "")
  for (covariance in c("gl", "h")) {
    # Preserve these inputs and record real R refusals as well as fitted values.
    f <- tryCatch(dosresmeta(logrr ~ dose, id=id, type=type, se=se, cases=cases, n=n,
      data=d, covariance=covariance, proc="2stage", method="fixed"), error=identity)
    result <- if (inherits(f, "error")) paste0('"ok":false,"error":', str(conditionMessage(f))) else {
      stopifnot(all(is.finite(coef(f))), all(is.finite(vcov(f))))
      paste0('"ok":true,"coef":', vec(coef(f)), ',"vcov":', vec(vcov(f)))
    }
    items <- c(items, paste0('{"type":"', type, '","covariance":"', covariance,
      '","rows":[', paste(rows, collapse=","), '],', result, '}'))
    cat(type, covariance, if (inherits(f, "error")) conditionMessage(f) else "fit", "\n")
  }
}
fixture <- paste0('{"R":"', R.version.string, '","dosresmeta":"', packageVersion("dosresmeta"),
  '","mixmeta":"', packageVersion("mixmeta"), '","cases":[', paste(items, collapse=","), ']}')
dir.create("hub/shared/tests/fixtures", showWarnings=FALSE)
writeLines(fixture, "hub/shared/tests/fixtures/rev-p02-r3-r.json")
cat(R.version.string, "\ndosresmeta", as.character(packageVersion("dosresmeta")),
  "\nmixmeta", as.character(packageVersion("mixmeta")), "\nWrote 6 valid-count parity references (fits or R refusals).\n")
